#pragma once

#include "ArgusContainerAllocator.h"
#include "ComponentDefinitions/TaskComponent.h"

class ITaskComponentObserver
{
public:
	virtual void OnChanged_m_baseState(const EBaseState& oldValue, const EBaseState& newValue) = 0;
	virtual void OnChanged_m_flightState(const EFlightState& oldValue, const EFlightState& newValue) = 0;
};

class TaskComponentObservers
{
private:
	TArray<ITaskComponentObserver*, ArgusContainerAllocator<2u> > m_TaskComponentObservers;

public:
	void AddObserver(ITaskComponentObserver* observer)
	{
		if (!observer)
		{
			return;
		}

		m_TaskComponentObservers.Add(observer);
	}

	void RemoveObserver(ITaskComponentObserver* observer)
	{
		if (!observer)
		{
			return;
		}

		m_TaskComponentObservers.RemoveAll
		(
			[observer] (ITaskComponentObserver* other)
			{
				return other == observer;
			}
		);
	}

	void Reset()
	{
		m_TaskComponentObservers.Reset();
	}

private:
	void OnChanged_m_baseState(const EBaseState& oldValue, const EBaseState& newValue)
	{
		for (int32 i = 0; i < m_TaskComponentObservers.Num(); ++i)
		{
			m_TaskComponentObservers[i]->OnChanged_m_baseState(oldValue, newValue);
		}
	};
	void OnChanged_m_flightState(const EFlightState& oldValue, const EFlightState& newValue)
	{
		for (int32 i = 0; i < m_TaskComponentObservers.Num(); ++i)
		{
			m_TaskComponentObservers[i]->OnChanged_m_flightState(oldValue, newValue);
		}
	};

	friend struct TaskComponent;
};
